<?php
namespace WPMailDesk\WordPress;
use WPMailDesk\Infrastructure\Database\Repository;
final class SiteHealth{public function __construct(private Repository$r){}public function register():void{add_filter('site_status_tests',function($tests){$tests['direct']['wpmd_crypto']=array('label'=>'MailDesk encryption','test'=>array($this,'crypto'));$tests['direct']['wpmd_cron']=array('label'=>'MailDesk queue','test'=>array($this,'cron'));return$tests;});}public function crypto():array{$ok=function_exists('sodium_crypto_secretbox')||extension_loaded('openssl');return array('label'=>$ok?'MailDesk encryption is available':'MailDesk cannot encrypt secrets','status'=>$ok?'good':'critical','badge'=>array('label'=>'MailDesk','color'=>'blue'),'description'=>'<p>'.esc_html($ok?'Authenticated encryption support is available.':'Install Sodium or OpenSSL before storing mail credentials.').'</p>','actions'=>'','test'=>'wpmd_crypto');}public function cron():array{$next=wp_next_scheduled('wpmd_queue_tick');return array('label'=>$next?'MailDesk queue is scheduled':'MailDesk queue is not scheduled','status'=>$next?'good':'recommended','badge'=>array('label'=>'MailDesk','color'=>'blue'),'description'=>'<p>'.esc_html($next?'Background delivery is scheduled.':'Reactivate the plugin or configure a real system cron for reliable mail processing.').'</p>','actions'=>'','test'=>'wpmd_cron');}}
